import {createApi} from './focus-api.mjs';
import {esc,when} from './customer-shared.mjs';
const api=createApi(),root=document.querySelector('#content'),status=document.querySelector('#status');let identity,tab='analytics',cases=[],generation=0,selectedCase='',latestReceipt;
const allowed=p=>({admin:['private','manage','approve','payment','team','audit','analyze'],manager:['private','manage','approve','payment','audit','analyze'],analyst:['analyze'],'read-only':[]}[identity?.role]||[]).includes(p);
const disabled=p=>allowed(p)?'':'disabled';
const date=x=>x?esc(when(x)):'Not recorded';
const money=(n,c)=>{try{return new Intl.NumberFormat(undefined,{style:'currency',currency:c}).format(n/100)}catch{return esc(c)+' '+(n/100).toFixed(2)}};
function download(value,name,type='application/json'){const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){return '\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+\-@\t\r\n]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');}
function fail(e){status.textContent=e.message||'Unable to load records.';}
async function run(button,fn){button.disabled=true;status.textContent='Working…';try{await fn();status.textContent='Saved.';}catch(e){fail(e);}finally{button.disabled=false;}}
const caseOptions=()=>cases.map(s=>`<option value="${esc(s.id)}" ${s.id===selectedCase?'selected':''}>${esc(s.customerName)} · ${esc(s.id)}</option>`).join('');
function chart(rows){const max=Math.max(1,...rows.map(r=>r.opened)),width=1000,step=width/rows.length;return `<svg class="chart" viewBox="0 0 1000 160" role="img" aria-label="Cases opened and currently verified, grouped by case creation date">${rows.map((r,i)=>`<g><title>${esc(r.date)}: ${r.opened} opened, ${r.verified} currently verified</title><rect x="${i*step+1}" y="${150-r.opened/max*135}" width="${Math.max(1,step*.45)}" height="${r.opened/max*135}"/><rect class="verified" x="${i*step+step*.5}" y="${150-r.verified/max*135}" width="${Math.max(1,step*.45)}" height="${r.verified/max*135}"/></g>`).join('')}</svg>`;}
async function analytics(ticket){const data=await api('analytics');if(ticket!==generation)return;root.innerHTML=`<section><span class="eyebrow">MEASURED OUTCOMES</span><h2>Recovery analytics</h2><form class="filters" id="dates"><label>From (UTC)<input type="date" name="from" value="${data.from}" required></label><label>Through (UTC)<input type="date" name="to" value="${data.to}" required></label><label>Payment source<select name="source"><option value="all">All records</option><option value="sample">Illustrative sample</option><option value="paypal-sandbox">PayPal sandbox</option></select></label><button class="primary">Apply filters</button><button type="button" id="export-report">Export report CSV</button></form><div id="report"></div></section>`;
 let report=data;function paint(d){report=d;root.querySelector('#report').innerHTML=`<div class="metrics">${[['Recorded recovery rate',d.historicalRecoveryRate===null?'—':Math.round(d.historicalRecoveryRate*100)+'%',d.historicallyVerified+' passed at least once / '+d.total+' cases · '+d.verified+' currently verified'],['Open cases',d.open,'Cases without current verified proof'],['Average recovery',d.averageRecoveryMinutes===null?'—':Math.round(d.averageRecoveryMinutes)+' min','Opened to the first recorded passing verification'],['Unsuccessful checks',d.unsuccessful,'Latest verification failed; still open']].map(([label,v,note])=>`<div class="metric"><strong>${v}</strong><span>${label}</span><small>${note}</small></div>`).join('')}</div><p class="notice">${esc(d.definition)} ${d.sampleCases} sample cases · ${d.providerCases} PayPal sandbox cases.</p><h3>Purchase value by currency</h3><div class="table-wrap"><table><thead><tr><th>Currency</th><th>Verified access value</th><th>Outstanding access / at risk</th><th>Payment not complete</th></tr></thead><tbody>${d.amounts.map(a=>`<tr><td>${esc(a.currency)}</td><td>${money(a.verifiedMinor,a.currency)}</td><td>${money(a.atRiskMinor,a.currency)}</td><td>${money(a.pendingPaymentMinor,a.currency)}</td></tr>`).join('')||'<tr><td colspan="4">No cases in this range.</td></tr>'}</tbody></table></div><h3>Daily cohort trends</h3><p>Blue: opened · Green: currently verified. Grouped by case creation date.</p>${chart(d.trend)}<details><summary>View daily data table</summary><div class="table-wrap"><table><tr><th>Date (UTC)</th><th>Opened</th><th>Currently verified</th></tr>${d.trend.map(r=>`<tr><td>${r.date}</td><td>${r.opened}</td><td>${r.verified}</td></tr>`).join('')}</table></div></details>`;}
 paint(data);root.querySelector('#dates').onsubmit=async e=>{e.preventDefault();const b=e.submitter;await run(b,async()=>{const q=new URLSearchParams(new FormData(e.target));const d=await api('analytics?'+q);if(ticket===generation)paint(d);});};
 root.querySelector('#export-report').onclick=()=>download(csv([['fromUTC','throughUTC','cases','verified','open','latestFailed','currentVerifiedRate','averageMinutes','historicallyVerified','historicalRecoveryRate'],[report.from,report.to,report.total,report.verified,report.open,report.unsuccessful,report.recoveryRate,report.averageRecoveryMinutes,report.historicallyVerified,report.historicalRecoveryRate],[],['currency','verifiedMinor','atRiskMinor','pendingPaymentMinor'],...report.amounts.map(a=>[a.currency,a.verifiedMinor,a.atRiskMinor,a.pendingPaymentMinor]),[],['dateUTC','opened','verified'],...report.trend.map(r=>[r.date,r.opened,r.verified])]),'paytrace-analytics.csv','text/csv;charset=utf-8');
}
async function notifications(ticket){const {items}=await api('notifications');if(ticket!==generation)return;root.innerHTML=`<section><div class="actions"><h2>Smart notifications</h2><button id="refresh-notifications">Refresh notifications</button></div><p>Workspace alerts for authorized team members. Resolved conditions leave the active list. Read status is shared within this workspace.</p>${items.map(n=>`<article class="notification"><div><span class="pill ${n.readAt?'':'warn'}">${esc(n.kind.replaceAll('-',' '))} ${n.readAt?'· Read':'· Unread'}</span><p>${esc(n.text)}</p><small>${esc(n.caseId)} · ${date(n.at)}</small></div><button data-case="${esc(n.caseId)}">Review case</button><button data-read="${esc(n.id)}" ${n.readAt?'disabled':''}>Mark read</button></article>`).join('')||'<p>No active alerts. Refresh after a case changes.</p>'}</section>`;root.querySelector('#refresh-notifications').onclick=()=>show('notifications');root.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{selectedCase=b.dataset.case;show('verification');});root.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>run(b,async()=>{await api('notifications/read',{id:b.dataset.read});await show('notifications');}));}
async function verification(ticket){const ops=await api('operations');if(ticket!==generation)return;cases=ops.cases;if(!cases.length){root.innerHTML='<section><h2>No recovery cases yet</h2><p>Create a case with the learner and purchase details before generating a receipt.</p><a class=button href=focus.html>Open recovery desk</a></section>';return;}if(!cases.some(s=>s.id===selectedCase))selectedCase=cases[0]?.id||'';root.innerHTML=`<section><h2>Recovery Receipt & Verification Center</h2><p>Trace the approval, access grant and current verification evidence for one purchase.</p><label>Case<select id="receipt-case">${caseOptions()}</select></label><div id="receipt"></div></section><section><h2>Customer & case history</h2><p>Case changes, payment attempts, approvals and outreach metadata. Message text, addresses and private notes stay in the restricted communication desk.</p><div id="timeline"></div></section>`;
 async function load(){const caseId=selectedCase;const [r,h]=await Promise.all([api('verification?caseId='+encodeURIComponent(caseId)),allowed('private')?api('history?caseId='+encodeURIComponent(caseId)):Promise.resolve({items:[]})]);if(ticket!==generation||caseId!==selectedCase)return;latestReceipt=r;root.querySelector('#receipt').innerHTML=`<div class="card"><div class="actions"><h2>Recovery Receipt</h2><span class="pill ${r.status==='Verified'?'good':'warn'}">${esc(r.status)}</span><span class="pill">${esc(r.source)}</span></div><dl class="details"><dt>Receipt</dt><dd>${esc(r.receiptId)}</dd><dt>Case ID</dt><dd>${esc(r.caseId)}</dd><dt>Approval</dt><dd>${r.approval?(r.approval.role==='unknown'?'Approval recorded':esc(r.approval.role)+' approved exact plan')+' · '+date(r.approval.at):'Not recorded'}</dd><dt>Last provider status</dt><dd>${esc(r.providerStatus)} · ${date(r.providerCheckedAt)}</dd><dt>Access grant</dt><dd>${r.access.grants} grant(s) recorded</dd><dt>Last passed check</dt><dd>${date(r.freshness?.lastVerifiedAt)}</dd><dt>Evidence expires</dt><dd>${date(r.freshness?.expiresAt)}</dd><dt>Payment hold</dt><dd>${esc(r.freshness?.paymentHold?.status||'None')}</dd><dt>Verification</dt><dd>${r.access.verified?'Current checks passed':'A fresh verification is required'} · ${date(r.access.checkedAt)}</dd><dt>Audit record</dt><dd>${r.audit.valid?'Chain checks pass':'Integrity mismatch — investigate'} · ${r.audit.checked} entries · ${r.audit.keyed?'Keyed':'Unkeyed'}</dd><dt>Checkpoint</dt><dd class="digest">${esc(r.audit.head)}</dd></dl><h3>Checks recorded at ${date(r.access.checkedAt)}</h3><p class=muted>These are historical results when the receipt is expired.</p>${r.checks.map(c=>`<p>${c.ok?'✓':'○'} ${esc(c.label)}</p>`).join('')}<p class="notice">${esc(r.notice)} ${esc(r.audit.assurance)}</p><div class="actions"><button id="download-receipt">Download receipt JSON</button><button id="print-receipt">Print receipt</button></div></div>`;root.querySelector('#timeline').innerHTML=`<ol class="timeline">${h.items.map(e=>`<li><small>${date(e.at)} · ${esc(e.type)}</small>${esc(e.text)}</li>`).join('')||'<li>Detailed history requires a Manager or Admin role.</li>'}</ol>`;root.querySelector('#download-receipt').onclick=()=>download(latestReceipt,r.receiptId+'.json');root.querySelector('#print-receipt').onclick=()=>window.print();}
 root.querySelector('#receipt-case').onchange=async e=>{selectedCase=e.target.value;try{await load();}catch(e){fail(e);}};await load();
}
async function priorities(ticket){const data=await api('prioritization');if(ticket!==generation)return;root.innerHTML=`<section><div class="actions"><h2>Explainable case prioritization</h2><button id="ai-rank" ${disabled('analyze')}>Ask AI for a second look</button></div><p>Rankings are suggestions. They never approve a repair, save a priority, transfer access, or send a message. AI receives case IDs, age, value and status; no customer messages or email addresses.</p><div id="rankings"></div></section>`;function paint(d){root.querySelector('#rankings').innerHTML=`<span class="pill">${esc(d.mode)}</span><p class="notice">${esc(d.notice)}</p>${d.recommendations.map((r,i)=>`<article class="rank"><span class="score">${i+1}.</span> <b>${esc(r.caseId)}</b><p>${esc(r.reasons.join(' · '))}</p>${r.aiReason?'<p>AI suggestion: '+esc(r.aiReason)+'</p>':''}<small>${r.ageHours} hours old · ${money(r.amountMinor,r.currency)} · ${esc(r.status)}</small></article>`).join('')||'<p>No open cases need prioritization.</p>'}`;}paint(data);root.querySelector('#ai-rank').onclick=e=>run(e.target,async()=>{const d=await api('prioritization',{});if(ticket===generation)paint(d);});}
async function operations(ticket){if(!allowed('team')){root.innerHTML='<section><h2>Operations access restricted</h2><p>Only a workspace Admin can inspect or retry system jobs.</p></section>';return;}const d=await api('operations/status');if(ticket!==generation)return;root.innerHTML=`<section><h2>Operations & deployment checks</h2><p>Configuration and runtime health are shown separately from live acceptance. A configured service has not necessarily passed a live test.</p><div class="metrics"><div class="metric"><strong>${d.database?'OK':'Error'}</strong><span>Database integrity</span></div><div class="metric"><strong>${d.worker.running?'Active':'Waiting'}</strong><span>Durable worker</span><small>${date(d.worker.lastRun)}</small></div><div class="metric"><strong>${d.backup?.restoreVerified?'Verified':'Not run'}</strong><span>Backup restore probe</span><small>${date(d.backup?.at)}</small></div><div class="metric"><strong>${d.liveAcceptance.verified?'Recorded':'Needs setup'}</strong><span>Live acceptance evidence</span></div></div><dl class="details"><dt>Verified sign-in</dt><dd>${d.authentication.configured?'Configured':'Not configured'} · MFA ${d.authentication.mfaRequired?'required':'not required'}</dd><dt>Course platform</dt><dd>${d.courseConnector?'External connector configured':'Local demonstration access store'}</dd><dt>Audit protection</dt><dd>${d.audit.keyed?'HMAC keyed':'Unkeyed'} · checkpoint ${d.audit.checkpoint?.external?'external':d.audit.checkpoint?'local':'not run'}</dd><dt>Encrypted backups</dt><dd>${d.backup?.encrypted?'Yes':d.backup?'No':'Not run'}</dd></dl><p class="notice">${esc(d.deployment)} Global maintenance requires an authorized server operator; verified owner accounts satisfy that gate.</p><div class="actions"><button id="ops-refresh">Refresh operations</button><button id="ops-run" ${identity.operator?'':'disabled'}>Run due jobs</button><button id="ops-backup" ${identity.operator?'':'disabled'}>Queue backup & restore probe</button></div></section><section><h2>Durable jobs</h2><div class="table-wrap"><table><tr><th>Job</th><th>State</th><th>Attempts</th><th>Next due</th><th>Action</th></tr>${d.jobs.map(j=>`<tr><td>${esc(j.kind)}</td><td>${esc(j.state)} ${esc(j.error||'')}</td><td>${j.attempts} / ${j.maxAttempts}</td><td>${date(new Date(j.due).toISOString())}</td><td>${j.state==='failed'&&(j.owner!==null||identity.operator)?'<button data-retry="'+esc(j.id)+'">Retry failed job</button>':'—'}</td></tr>`).join('')}</table></div></section><section><h2>Recent operational events</h2>${d.events.map(e=>`<p><small>${date(new Date(e.at).toISOString())} · ${esc(e.level)}</small><br>${esc(e.kind)} · ${esc(e.detail)}</p>`).join('')||'<p>No failures recorded.</p>'}</section>`;root.querySelector('#ops-refresh').onclick=()=>show('operations');root.querySelector('#ops-run').onclick=e=>run(e.target,async()=>{await api('operations/run',{});await show('operations');});root.querySelector('#ops-backup').onclick=e=>run(e.target,async()=>{await api('operations/backup',{});status.textContent='Backup queued. Refresh operations after the worker runs.';});root.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>run(b,async()=>{await api('operations/retry',{id:b.dataset.retry});await show('operations');}));}
async function payments(ticket){const d=await api('providers');if(ticket!==generation)return;root.innerHTML=`<section><h2>Payment provider verification</h2><p>PayPal sandbox checkout, idempotent capture, signature-verified webhooks and authoritative reconciliation. Raw card information is never stored.</p><div class="metrics"><div class="metric"><strong>PayPal</strong><span>Sandbox only</span><small>${d.paypal.configured?'Credentials configured':'Credentials needed'}</small></div><div class="metric"><strong>Webhooks</strong><span>${d.paypal.webhookConfigured?'Listener configured':'Setup needed'}</span><small>Signatures checked through PayPal</small></div></div><p class="notice">A webhook never grants access or trusts the event payload as current payment evidence. It schedules fresh provider reads. Duplicate events are recorded once. Live provider acceptance still requires a real sandbox checkout and registered webhook.</p><div class="actions"><button id="reconcile" ${disabled('payment')}>Reconcile payment records</button><a class="button" href="focus.html">Open checkout & recovery desk</a><a class="button" href="guide.html">Provider setup guide ↗</a></div><p id="reconcile-result"></p></section>`;root.querySelector('#reconcile').onclick=e=>run(e.target,async()=>{const r=await api('paypal/reconcile',{});if(ticket===generation)root.querySelector('#reconcile-result').textContent=r.cases+' cases checked at '+when(r.checkedAt)+'. '+r.notice;});}
async function automation(ticket){const data=await api('automation');if(ticket!==generation)return;root.innerHTML=`<section><span class="eyebrow">BOUNDED FOLLOW-UPS</span><h2>Automated recovery workflows</h2><p>Schedule internal follow-ups and manager escalations based on case age, customer replies and payment status. Verified cases and running recovery jobs are skipped.</p><form id="automation"><label class="check"><input type="checkbox" name="enabled" ${data.enabled?'checked':''} ${disabled('manage')}> Enable scheduled follow-ups</label><div class="filters"><label>First follow-up (hours)<input name="delayHours" type="number" min="1" max="720" value="${data.delayHours}" required></label><label>Minimum gap (hours)<input name="cooldownHours" type="number" min="24" max="720" value="${data.cooldownHours}" required></label><label>Maximum per case<input name="maxPerCase" type="number" min="1" max="5" value="${data.maxPerCase}" required></label><label>Escalate after (hours)<input name="escalateHours" type="number" min="1" max="1440" value="${data.escalateHours}" required></label></div><p class="notice">Email is off by default. Enabling it authorizes generic follow-up messages to the verified contact saved in each case. Requires configured Resend delivery. No automatic charge, access change or approval is permitted.</p><label class="check"><input type="checkbox" name="emailEnabled" ${data.emailEnabled?'checked':''} ${disabled('manage')}> Authorize bounded customer email follow-ups</label><p>Customer replies pause automated customer email and create an internal review task. Limits persist across restarts.</p><div class="actions"><button class="primary" ${disabled('manage')}>Save workflow settings</button><button id="run-workflows" type="button" ${disabled('manage')}>Check workflows now</button></div></form></section>`;root.querySelector('#automation').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),value={enabled:f.has('enabled'),emailEnabled:f.has('emailEnabled')};for(const k of ['delayHours','cooldownHours','maxPerCase','escalateHours'])value[k]=Number(f.get(k));run(e.submitter,()=>api('automation',value));};root.querySelector('#run-workflows').onclick=e=>run(e.target,async()=>{const r=await api('automation/run',{});root.insertAdjacentHTML('beforeend',`<p role="status">${r.scheduled} new follow-up(s) scheduled. See Notifications.</p>`);});}
async function audit(ticket){if(!allowed('audit')){root.innerHTML='<section><h2>Audit access restricted</h2><p>Admin and Manager roles can search and export the audit log.</p></section>';return;}root.innerHTML=`<section><h2>Security audit log</h2><p>Successful and denied access, priority edits, approvals, recovery attempts and team changes. Search by case, actor or action.</p><form id="audit-search" class="filters"><label>Search<input name="search" maxlength="100" placeholder="Case ID, action or actor"></label><button>Search audit</button><button type="button" id="audit-export">Export visible checkpoint</button></form><div id="audit-data"></div><button id="older-audit" hidden>Load older entries</button></section>`;let visible=[],integrity,before=null,query='';async function load(older=false){const d=await api('audit?'+new URLSearchParams({search:query,...(older&&before?{before}:{}),limit:100}));if(ticket!==generation)return;before=d.nextBefore;visible=older?[...visible,...d.items]:d.items;integrity=d.integrity;root.querySelector('#audit-data').innerHTML=`<p class="notice">${d.integrity.valid?'Chain integrity checks pass.':'Integrity mismatch detected.'} ${esc(d.integrity.assurance)}</p><p class="digest">Checkpoint: ${esc(d.integrity.head)}</p><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor / role</th><th>Action</th><th>Case</th><th>Outcome</th></tr></thead><tbody>${visible.map(e=>`<tr><td>${date(e.at)}</td><td>${esc(e.actor)}<br>${esc(e.role)}</td><td>${esc(e.action)}</td><td>${esc(e.caseId||'—')}</td><td>${esc(e.outcome)}</td></tr>`).join('')}</tbody></table></div>`;root.querySelector('#older-audit').hidden=!before;}
 root.querySelector('#audit-search').onsubmit=e=>{e.preventDefault();query=new FormData(e.target).get('search');run(e.submitter,()=>load());};root.querySelector('#older-audit').onclick=e=>run(e.target,()=>load(true));root.querySelector('#audit-export').onclick=()=>download({integrity,items:visible},'paytrace-audit-checkpoint.json');await load();}
async function team(ticket){if(!allowed('team')){root.innerHTML=`<section><h2>Your team access</h2><p>Signed in as ${esc(identity.actor)} · ${esc(identity.role)}. Only the workspace Admin can invite or revoke team access.</p><button id="logout-team">Leave team session</button></section>`;root.querySelector('#logout-team').onclick=e=>run(e.target,async()=>{await api(identity.productionAuthentication?'auth/logout':'team/logout',{});location.href=identity.productionAuthentication?'account.html':location.pathname;});return;}const {items}=await api('team');if(ticket!==generation)return;root.innerHTML=`<section><h2>Role-based access</h2><p>Admin: team and all controls. Manager: customer data, approvals, payments and audit. Analyst: redacted case review and investigation. Read-Only: redacted reports, receipts and alerts.</p><p class="notice">${identity.productionAuthentication?'Membership invitations require a verified email, MFA sign-in and explicit acceptance. Revocation invalidates workspace sessions immediately.':'Demonstration mode uses expiring bearer links. These are separate from verified-account memberships. Keep links private and revoke them when no longer needed.'}</p>${!identity.operator?'<form id="unlock" class="filters"><label>Owner operator key<input type="password" autocomplete="off" name="key" required></label><button>Unlock invitations</button></form>':''}<form id="invite" class="filters"><label>${identity.productionAuthentication?'Verified member email':'Member label'}<input name="label" type="${identity.productionAuthentication?'email':'text'}" maxlength="${identity.productionAuthentication?254:60}" required></label><label>Role<select name="role"><option value="read-only">Read-Only</option><option value="analyst">Analyst</option><option value="manager">Manager</option></select></label><label>Expires in hours<input name="ttlHours" type="number" min="1" max="168" value="24" required></label><button class="primary" ${identity.operator?'':'disabled'}>Create private access link</button></form><div id="invite-result"></div><h3>Issued access</h3><div class="table-wrap"><table><tr><th>Label</th><th>Role</th><th>Expires</th><th>Access</th></tr>${items.map(m=>`<tr><td>${esc(m.label)}</td><td>${esc(m.role)}</td><td>${m.expires?date(new Date(m.expires).toISOString()):'Durable membership'}</td><td>${m.revoked?'Revoked':m.role==='admin'?'Owner Admin':`<button data-revoke="${esc(m.id)}">Revoke access</button>`}</td></tr>`).join('')}</table></div></section>`;
 const unlock=root.querySelector('#unlock');if(unlock)unlock.onsubmit=e=>{e.preventDefault();const key=new FormData(e.target).get('key');run(e.submitter,async()=>{await api('operator',{key});e.target.reset();identity=await api('identity');await show('team');});};root.querySelector('#invite').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);run(e.submitter,async()=>{const r=await api('team/invite',{label:f.get('label'),role:f.get('role'),ttlHours:Number(f.get('ttlHours'))});root.querySelector('#invite-result').innerHTML=`<p class="notice">Private access link (shown once). Share only with the intended member. Expires ${date(r.expires)}.</p><input aria-label="Private team access link" readonly value="${esc(r.url)}" style="width:100%"><p><button id="refresh-team">Refresh issued access</button></p>`;root.querySelector('#refresh-team').onclick=()=>show('team');});};root.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=()=>run(b,async()=>{await api('team/revoke',{id:b.dataset.revoke});await show('team');}));}
async function show(name){tab=name;const ticket=++generation;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-current',b.dataset.tab===name?'page':'false'));status.textContent='';root.innerHTML='<section><p>Loading current records…</p></section>';try{await ({analytics,notifications,verification,priorities,payments,automation,audit,team,operations}[name])(ticket);}catch(e){if(ticket!==generation)return;root.innerHTML='<section><h2>Records unavailable</h2><p>The last operation is not confirmed. Refresh this section to retry.</p><button id="retry">Retry section</button></section>';root.querySelector('#retry').onclick=()=>show(tab);fail(e);}}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>show(b.dataset.tab));
async function init(){try{if(window.COURSELATCH_RUNTIME?.authRequired){const session=await api('auth/session');if(!session.account?.owner){location.href='account.html';return;}}if(!window.COURSELATCH_RUNTIME?.backend)throw Error('Run the Node backend to use the Recovery Center. The static simulation does not issue team access or audit records.');await api('state');identity=await api('identity');document.querySelector('#identity').textContent=identity.actor+' · '+identity.role;const params=new URLSearchParams(location.hash.slice(1)),token=params.get('team');if(token){history.replaceState(null,'',location.pathname);const join=document.querySelector('#join');join.hidden=false;join.innerHTML='<h2>Private team invitation</h2><p>Accept this link to enter the inviting workspace with its assigned role.</p><button id="accept-team">Accept team access</button>';join.querySelector('button').onclick=e=>run(e.target,async()=>{await api('team/session',{token});location.reload();});}await show('analytics');}catch(e){root.innerHTML=window.COURSELATCH_RUNTIME?.backend?'<section><h2>Session unavailable</h2><p>Your team access may have expired or been revoked. Leave the team session to return to your own demo workspace.</p><button id=leave-session>Leave team session</button></section>':'<section><h2>Recovery Center needs the backend</h2><p>Start the app with npm start, then open this page from the recovery desk.</p></section>';const leave=root.querySelector('#leave-session');if(leave)leave.onclick=e=>run(e.target,async()=>{await api('team/logout',{});location.reload();});fail(e);}}
init();
